css:
:where(.wtyg-map-site_ufo_pre1900) *,:where(.wtyg-map-site_ufo_pre1900) *::before,:where(.wtyg-map-site_ufo_pre1900) *::after{box-sizing: border-box; margin: 0; padding: 0;}
:where(.wtyg-map-site_ufo_pre1900){--bg: #f0ede8; --surface: #ffffff; --ink: #1a1a1a; --ink2: #4a4a4a;
  --ink3: #909090; --rule: #ddd9d3; --accent: #1d3d5c; --accent-lt: #2e5a87;
  --serif: 'Cormorant Garamond', Georgia, serif; --sans: 'DM Sans', system-ui, sans-serif;
  --era-prehistoric: #8a6a4a; --era-ancient: #5a3a2a; --era-roman: #6a2a2a;
  --era-medieval: #2a4a6a; --era-renaissance: #3a5a3a; --era-modern: #4a3a5a;
  --era-airship: #2a3a4a;
  --rate-high: #1a5e3a; --rate-mid: #8a6a18; --rate-low: #8a3a18; --rate-none: #1d3d5c;}
:where(.wtyg-map-site_ufo_pre1900),:where(.wtyg-map-site_ufo_pre1900){height: 100%; background: var(--bg); color: var(--ink);
  font-family: var(--sans); font-size: 14px; overflow: hidden;}
:where(.wtyg-map-site_ufo_pre1900) .app{display: flex; flex-direction: column; height: 100vh; overflow: hidden;}
:where(.wtyg-map-site_ufo_pre1900) .app-body{display:flex; flex-direction:row; flex:1; min-height:0; overflow:hidden;}
:where(.wtyg-map-site_ufo_pre1900) .map-side{width:380px; flex-shrink:0; display:flex; flex-direction:column;
  border-right:2px solid var(--rule); background:#0d1520; position:relative;}
:where(.wtyg-map-site_ufo_pre1900) .right-side{flex:1; display:flex; flex-direction:column; min-width:0; overflow:hidden;}
:where(.wtyg-map-site_ufo_pre1900) .header{flex-shrink:0; padding:14px 40px 12px; border-bottom:1px solid var(--rule);
  background:var(--bg); display:flex; align-items:flex-end;
  justify-content:space-between; gap:20px;}
:where(.wtyg-map-site_ufo_pre1900) .header-left{}
:where(.wtyg-map-site_ufo_pre1900) .header-kicker{font-size:9px; font-weight:500; letter-spacing:3px;
  text-transform:uppercase; color:var(--ink3); margin-bottom:4px;}
:where(.wtyg-map-site_ufo_pre1900) .header-title{font-family:var(--serif); font-size:22px; font-weight:600;
  color:var(--ink); letter-spacing:0.3px; line-height:1;}
:where(.wtyg-map-site_ufo_pre1900) .header-title em{color:var(--accent); font-style:normal;}
:where(.wtyg-map-site_ufo_pre1900) .header-stats{display:flex; gap:20px;}
:where(.wtyg-map-site_ufo_pre1900) .stat{text-align:right;}
:where(.wtyg-map-site_ufo_pre1900) .stat-num{font-family:var(--serif); font-size:20px; font-weight:600; color:var(--accent);}
:where(.wtyg-map-site_ufo_pre1900) .stat-label{font-size:9px; letter-spacing:2px; text-transform:uppercase; color:var(--ink3);}
:where(.wtyg-map-site_ufo_pre1900) .notice-bar{flex-shrink:0; background:#e8edf2; border-bottom:1px solid #c8d4df;
  padding:8px 40px; display:flex; align-items:center; gap:10px;}
:where(.wtyg-map-site_ufo_pre1900) .notice-icon{font-size:13px; flex-shrink:0;}
:where(.wtyg-map-site_ufo_pre1900) .notice-text{font-size:11.5px; color:#2a4a64; line-height:1.5;}
:where(.wtyg-map-site_ufo_pre1900) .notice-text strong{font-weight:600;}
:where(.wtyg-map-site_ufo_pre1900) :is([data-wtyg-id="map"],#wtyg-noid-map){width:100%; height:100%;}
:where(.wtyg-map-site_ufo_pre1900) .map-side-label{position:absolute; top:8px; left:10px; z-index:1000;
  font-size:8px; font-weight:500; letter-spacing:2.5px; text-transform:uppercase;
  color:rgba(255,255,255,0.7); pointer-events:none; text-shadow:0 1px 3px rgba(0,0,0,0.8);}
:where(.wtyg-map-site_ufo_pre1900) .map-legend{position:absolute; bottom:25px; left:8px; z-index:1000;
  background:rgba(10,16,28,0.92); border:1px solid rgba(60,100,140,0.5); border-radius:3px;
  padding:8px 10px; font-size:9px; font-family:var(--sans);}
:where(.wtyg-map-site_ufo_pre1900) .map-legend-title{font-size:8px; letter-spacing:2px; text-transform:uppercase; 
  color:rgba(160,190,220,0.6); margin-bottom:6px;}
:where(.wtyg-map-site_ufo_pre1900) .map-legend-item{display:flex; align-items:center; gap:5px; color:rgba(200,220,240,0.82); 
  line-height:1.6; font-size:9px;}
:where(.wtyg-map-site_ufo_pre1900) .map-legend-dot{width:8px; height:8px; border-radius:50%; flex-shrink:0;}
:where(.wtyg-map-site_ufo_pre1900) .leaflet-popup-content-wrapper{background:rgba(10,14,26,0.95)!important; color:#fff!important;
  border:1px solid #2a4a7a!important; border-radius:4px!important;}
:where(.wtyg-map-site_ufo_pre1900) .leaflet-popup-tip{background:rgba(10,14,26,0.95)!important;}
:where(.wtyg-map-site_ufo_pre1900) .leaflet-popup-content{margin:10px 12px!important; font-family:var(--sans); font-size:11px; line-height:1.5;}
:where(.wtyg-map-site_ufo_pre1900) .popup-title{font-weight:600; color:#6af; margin-bottom:4px;}
:where(.wtyg-map-site_ufo_pre1900) .popup-date{color:#f8a8a8;}
:where(.wtyg-map-site_ufo_pre1900) .popup-region{color:#a8c8e8;}
:where(.wtyg-map-site_ufo_pre1900) .controls{flex-shrink:0; display:flex; align-items:center; gap:14px;
  padding:9px 40px; border-bottom:1px solid var(--rule); background:var(--surface); flex-wrap:wrap;}
:where(.wtyg-map-site_ufo_pre1900) .filter-label{font-size:9px; font-weight:500; letter-spacing:2.5px;
  text-transform:uppercase; color:var(--ink3); white-space:nowrap;}
:where(.wtyg-map-site_ufo_pre1900) .filters{display:flex; gap:5px; flex-wrap:wrap;}
:where(.wtyg-map-site_ufo_pre1900) .filter-btn{font-size:11px; font-weight:500; padding:4px 11px; border-radius:2px;
  border:1px solid var(--rule); background:transparent; color:var(--ink2);
  cursor:pointer; transition:all 0.14s; white-space:nowrap;}
:where(.wtyg-map-site_ufo_pre1900) .filter-btn:hover{border-color:var(--accent); color:var(--accent);}
:where(.wtyg-map-site_ufo_pre1900) .filter-btn.active{background:var(--accent); border-color:var(--accent); color:#fff;}
:where(.wtyg-map-site_ufo_pre1900) .search-wrap{position:relative; margin-left:auto;}
:where(.wtyg-map-site_ufo_pre1900) .search-icon{position:absolute; left:8px; top:50%; transform:translateY(-50%);
  width:12px; height:12px; color:var(--ink3);}
:where(.wtyg-map-site_ufo_pre1900) .search-wrap input{border:1px solid var(--rule); background:var(--bg);
  padding:5px 10px 5px 28px; font-family:var(--sans); font-size:12px;
  border-radius:2px; outline:none; width:180px; transition:border-color 0.15s;}
:where(.wtyg-map-site_ufo_pre1900) .search-wrap input:focus{border-color:var(--accent);}
:where(.wtyg-map-site_ufo_pre1900) .main-body{flex:1; overflow-y:auto; overflow-x:hidden; min-height:0;}
:where(.wtyg-map-site_ufo_pre1900) .main-body::-webkit-scrollbar{width:4px;}
:where(.wtyg-map-site_ufo_pre1900) .main-body::-webkit-scrollbar-thumb{background:var(--rule); border-radius:2px;}
:where(.wtyg-map-site_ufo_pre1900) .tl-section{border-bottom:2px solid var(--rule);}
:where(.wtyg-map-site_ufo_pre1900) .tl-section-header{display:flex; align-items:center; justify-content:space-between;
  padding:10px 40px 8px; border-bottom:1px solid var(--rule);}
:where(.wtyg-map-site_ufo_pre1900) .tl-section-label{font-size:9px; font-weight:500; letter-spacing:3px; text-transform:uppercase;}
:where(.wtyg-map-site_ufo_pre1900) .tl-section-title{font-family:var(--serif); font-size:15px; font-weight:600;
  color:var(--ink); margin-top:2px;}
:where(.wtyg-map-site_ufo_pre1900) .tl-section-count{font-size:11px; color:var(--ink3);}
:where(.wtyg-map-site_ufo_pre1900) .timeline-area{position:relative;}
:where(.wtyg-map-site_ufo_pre1900) .tl-scroll{height:280px; overflow-x:auto; overflow-y:hidden;
  cursor:grab; user-select:none; position:relative; background:var(--bg);}
:where(.wtyg-map-site_ufo_pre1900) .tl-scroll:active{cursor:grabbing;}
:where(.wtyg-map-site_ufo_pre1900) .tl-scroll::-webkit-scrollbar{height:3px;}
:where(.wtyg-map-site_ufo_pre1900) .tl-scroll::-webkit-scrollbar-thumb{background:var(--rule); border-radius:2px;}
:where(.wtyg-map-site_ufo_pre1900) .tl-inner{height:280px; position:relative; min-width:100%;}
:where(.wtyg-map-site_ufo_pre1900) .tl-rail{position:absolute; top:50%; left:0; right:0; height:1px;
  background:var(--rule); transform:translateY(-50%);}
:where(.wtyg-map-site_ufo_pre1900) .node{position:absolute; top:50%; transform:translateX(-50%) translateY(-50%);
  display:flex; align-items:center; cursor:pointer; z-index:5;}
:where(.wtyg-map-site_ufo_pre1900) .node.above{flex-direction:column-reverse;}
:where(.wtyg-map-site_ufo_pre1900) .node.below{flex-direction:column;}
:where(.wtyg-map-site_ufo_pre1900) .node-dot{width:9px; height:9px; border-radius:50%; background:var(--surface);
  border:1.5px solid var(--rule); flex-shrink:0; z-index:2; transition:all 0.15s;}
:where(.wtyg-map-site_ufo_pre1900) .node:hover .node-dot,:where(.wtyg-map-site_ufo_pre1900) .node.active .node-dot{border-color:var(--accent);
  background:var(--accent); transform:scale(1.35);}
:where(.wtyg-map-site_ufo_pre1900) .node-stem{width:1px; height:18px; background:var(--rule); flex-shrink:0;
  transition:background 0.15s;}
:where(.wtyg-map-site_ufo_pre1900) .node.active .node-stem{background:var(--accent); opacity:0.4;}
:where(.wtyg-map-site_ufo_pre1900) .node-card{width:175px; background:var(--surface); border:1px solid var(--rule);
  padding:8px 10px; border-radius:2px; box-shadow:0 1px 6px rgba(0,0,0,0.06);
  transition:border-color 0.15s, box-shadow 0.15s; pointer-events:none;}
:where(.wtyg-map-site_ufo_pre1900) .node:hover .node-card,:where(.wtyg-map-site_ufo_pre1900) .node.active .node-card{border-color:var(--accent);
  box-shadow:0 3px 14px rgba(29,61,92,0.13);}
:where(.wtyg-map-site_ufo_pre1900) .node-card-year{font-size:9px; font-weight:500; letter-spacing:1.5px;
  color:var(--ink3); margin-bottom:2px;}
:where(.wtyg-map-site_ufo_pre1900) .node-card-name{font-family:var(--serif); font-size:12px; font-weight:600;
  color:var(--ink); line-height:1.25; margin-bottom:3px;}
:where(.wtyg-map-site_ufo_pre1900) .node-card-region{font-size:9px; font-weight:500; letter-spacing:1px;
  text-transform:uppercase; color:var(--accent); margin-bottom:6px;}
:where(.wtyg-map-site_ufo_pre1900) .node-card-ratings{display:flex; flex-wrap:wrap; gap:4px 8px; margin-bottom:6px; 
  padding-top:6px; border-top:1px solid var(--rule);}
:where(.wtyg-map-site_ufo_pre1900) .node-rating{display:flex; align-items:center; gap:3px;}
:where(.wtyg-map-site_ufo_pre1900) .node-rating-label{font-size:7px; letter-spacing:0.5px; text-transform:uppercase; color:var(--ink3);}
:where(.wtyg-map-site_ufo_pre1900) .node-rating-pips{display:flex; gap:1.5px;}
:where(.wtyg-map-site_ufo_pre1900) .node-pip{width:4px; height:5px; background:var(--rule); border-radius:1px;}
:where(.wtyg-map-site_ufo_pre1900) .node-pip.g{background:var(--rate-high);}
:where(.wtyg-map-site_ufo_pre1900) .node-pip.y{background:var(--rate-mid);}
:where(.wtyg-map-site_ufo_pre1900) .node-pip.r{background:var(--rate-low);}
:where(.wtyg-map-site_ufo_pre1900) .node-pip.b{background:var(--rate-none);}
:where(.wtyg-map-site_ufo_pre1900) .node-source-tag{font-size:8px; padding:1px 4px; border-radius:2px; background:#e8edf2; color:#2a4a64;}
:where(.wtyg-map-site_ufo_pre1900) .node-card-alt{font-size:8px; color:var(--ink3); line-height:1.4; margin-top:4px;
  padding-top:5px; border-top:1px dashed var(--rule); font-style:italic;}
:where(.wtyg-map-site_ufo_pre1900) .tl-nav{position:absolute; right:32px; bottom:12px; display:flex; gap:6px; z-index:10;}
:where(.wtyg-map-site_ufo_pre1900) .nav-btn{width:28px; height:28px; background:var(--surface); border:1px solid var(--rule);
  border-radius:2px; cursor:pointer; display:flex; align-items:center;
  justify-content:center; font-size:13px; color:var(--ink2); transition:all 0.15s;}
:where(.wtyg-map-site_ufo_pre1900) .nav-btn:hover{border-color:var(--accent); color:var(--accent);}
:where(.wtyg-map-site_ufo_pre1900) .detail-panel{display:none; position:fixed; top:0; right:0; width:480px; height:100vh;
  background:var(--surface); border-left:2px solid var(--rule); z-index:200;
  flex-direction:column; box-shadow:-4px 0 20px rgba(0,0,0,0.1);}
:where(.wtyg-map-site_ufo_pre1900) .detail-panel.open{display:flex;}
:where(.wtyg-map-site_ufo_pre1900) .detail-header{padding:16px 24px; border-bottom:1px solid var(--rule);
  display:flex; justify-content:space-between; align-items:flex-start;}
:where(.wtyg-map-site_ufo_pre1900) .detail-close{width:28px; height:28px; border:1px solid var(--rule); background:transparent;
  border-radius:2px; cursor:pointer; font-size:16px; color:var(--ink2);}
:where(.wtyg-map-site_ufo_pre1900) .detail-close:hover{border-color:var(--accent); color:var(--accent);}
:where(.wtyg-map-site_ufo_pre1900) .detail-body{flex:1; overflow-y:auto; padding:20px 24px 30px;}
:where(.wtyg-map-site_ufo_pre1900) .detail-body::-webkit-scrollbar{width:4px;}
:where(.wtyg-map-site_ufo_pre1900) .detail-body::-webkit-scrollbar-thumb{background:var(--rule);}
:where(.wtyg-map-site_ufo_pre1900) .detail-kicker{font-size:9px; font-weight:500; letter-spacing:3px;
  text-transform:uppercase; color:var(--ink3); margin-bottom:4px;}
:where(.wtyg-map-site_ufo_pre1900) .detail-title{font-family:var(--serif); font-size:22px; font-weight:600;
  color:var(--ink); line-height:1.2; margin-bottom:16px;}
:where(.wtyg-map-site_ufo_pre1900) .detail-meta{display:flex; gap:16px; margin-bottom:20px; padding-bottom:16px;
  border-bottom:1px solid var(--rule); flex-wrap:wrap;}
:where(.wtyg-map-site_ufo_pre1900) .detail-meta-item{}
:where(.wtyg-map-site_ufo_pre1900) .detail-meta-label{font-size:9px; letter-spacing:2px; text-transform:uppercase;
  color:var(--ink3); margin-bottom:2px;}
:where(.wtyg-map-site_ufo_pre1900) .detail-meta-value{font-family:var(--serif); font-size:14px; font-weight:600; color:var(--ink);}
:where(.wtyg-map-site_ufo_pre1900) .detail-section{margin-bottom:20px;}
:where(.wtyg-map-site_ufo_pre1900) .detail-section-title{font-size:9px; font-weight:500; letter-spacing:2.5px;
  text-transform:uppercase; color:var(--ink3); margin-bottom:8px;}
:where(.wtyg-map-site_ufo_pre1900) .detail-text{font-size:13px; line-height:1.7; color:var(--ink2);}
:where(.wtyg-map-site_ufo_pre1900) .ratings-grid{display:grid; grid-template-columns:1fr 1fr 1fr; gap:12px; margin-bottom:20px;
  padding:14px; background:var(--bg); border-radius:4px; border:1px solid var(--rule);}
:where(.wtyg-map-site_ufo_pre1900) .rating-item{}
:where(.wtyg-map-site_ufo_pre1900) .rating-label{font-size:9px; letter-spacing:1.5px; text-transform:uppercase;
  color:var(--ink3); margin-bottom:4px;}
:where(.wtyg-map-site_ufo_pre1900) .rating-pips{display:flex; gap:3px; align-items:center;}
:where(.wtyg-map-site_ufo_pre1900) .rating-pip{width:8px; height:10px; background:var(--rule); border-radius:2px;}
:where(.wtyg-map-site_ufo_pre1900) .rating-pip.lit-high{background:var(--rate-high);}
:where(.wtyg-map-site_ufo_pre1900) .rating-pip.lit-mid{background:var(--rate-mid);}
:where(.wtyg-map-site_ufo_pre1900) .rating-pip.lit-low{background:var(--rate-low);}
:where(.wtyg-map-site_ufo_pre1900) .rating-pip.lit-none{background:var(--rate-none);}
:where(.wtyg-map-site_ufo_pre1900) .rating-text{font-size:10px; color:var(--ink2); margin-left:6px;}
:where(.wtyg-map-site_ufo_pre1900) .alt-box{background:#faf8f5; border:1px solid #e8e4dc; border-radius:4px;
  padding:12px 14px; margin-bottom:20px;}
:where(.wtyg-map-site_ufo_pre1900) .alt-title{font-size:9px; letter-spacing:2px; text-transform:uppercase;
  color:var(--ink3); margin-bottom:6px; display:flex; align-items:center; gap:6px;}
:where(.wtyg-map-site_ufo_pre1900) .alt-icon{font-size:12px;}
:where(.wtyg-map-site_ufo_pre1900) .alt-text{font-size:12px; line-height:1.6; color:var(--ink2);}
:where(.wtyg-map-site_ufo_pre1900) .alt-none{font-style:italic; color:var(--ink3);}
:where(.wtyg-map-site_ufo_pre1900) .detail-sources{margin-top:20px; padding-top:16px; border-top:1px solid var(--rule);}
:where(.wtyg-map-site_ufo_pre1900) .detail-sources a{font-size:11px; color:var(--accent); word-break:break-all; 
  display:block; margin-bottom:4px;}
:where(.wtyg-map-site_ufo_pre1900) .detail-sources a:hover{text-decoration:underline;}
:where(.wtyg-map-site_ufo_pre1900) .tl-summary{padding:18px 40px 22px; background:var(--surface); border-top:1px solid var(--rule);}
:where(.wtyg-map-site_ufo_pre1900) .tl-summary-label{font-size:9px; font-weight:500; letter-spacing:3px;
  text-transform:uppercase; color:var(--ink3); margin-bottom:6px;}
:where(.wtyg-map-site_ufo_pre1900) .tl-summary-text{font-size:12.5px; line-height:1.7; color:var(--ink2); max-width:900px;}
